59	    const std::vector<MergeTreeIndexPtr> & indices_to_recalc,
60	    const CompressionCodecPtr & default_codec_,
61	    const MergeTreeWriterSettings & writer_settings,
62	    const MergeTreeIndexGranularity & computed_index_granularity) const
63	{
64	    NamesAndTypesList ordered_columns_list;
65	    std::copy_if(columns_list.begin(), columns_list.end(), std::back_inserter(ordered_columns_list),
66	        [this](const auto & column) { return getColumnPosition(column.name) != std::nullopt; });
67	
68	    /// Order of writing is important in compact format
69	    ordered_columns_list.sort([this](const auto & lhs, const auto & rhs)
70	        { return *getColumnPosition(lhs.name) < *getColumnPosition(rhs.name); });
71	
72	    return std::make_unique<MergeTreeDataPartWriterCompact>(
73	        shared_from_this(), std::move(data_part_storage_builder), ordered_columns_list, metadata_snapshot,
