93	void MergeTreeDataPartCompact::loadIndexGranularity()
94	{
95	    //String full_path = getRelativePath();
96	
97	    if (columns.empty())
98	        throw Exception("No columns in part " + name, ErrorCodes::NO_FILE_IN_DATA_PART);
99	
100	    if (!index_granularity_info.is_adaptive)
101	        throw Exception("MergeTreeDataPartCompact cannot be created with non-adaptive granulary.", ErrorCodes::NOT_IMPLEMENTED);
102	
103	    auto marks_file_path = index_granularity_info.getMarksFilePath("data");
104	    if (!data_part_storage->exists(marks_file_path))
105	        throw Exception(
106	            ErrorCodes::NO_FILE_IN_DATA_PART,
107	            "Marks file '{}' doesn't exist",
108	            std::string(fs::path(data_part_storage->getFullPath()) / marks_file_path));
109	
110	    size_t marks_file_size = data_part_storage->getFileSize(marks_file_path);
111	
112	    auto buffer = data_part_storage->readFile(marks_file_path, ReadSettings().adjustBufferSize(marks_file_size), marks_file_size, std::nullopt);
113	    while (!buffer->eof())
114	    {
115	        /// Skip offsets for columns
116	        buffer->seek(columns.size() * sizeof(MarkInCompressedFile), SEEK_CUR);
117	        size_t granularity;
118	        readIntBinary(granularity, *buffer);
119	        index_granularity.appendMark(granularity);
120	    }
121	
122	    if (index_granularity.getMarksCount() * index_granularity_info.getMarkSizeInBytes(columns.size()) != marks_file_size)
123	        throw Exception("Cannot read all marks from file " + marks_file_path, ErrorCodes::CANNOT_READ_ALL_DATA);
124	
125	    index_granularity.setInitialized();
126	}
