139	void MergeTreeDataPartCompact::checkConsistency(bool require_part_metadata) const
140	{
141	    checkConsistencyBase();
142	    String mrk_file_name = DATA_FILE_NAME + index_granularity_info.marks_file_extension;
143	
144	    if (!checksums.empty())
145	    {
146	        /// count.txt should be present even in non custom-partitioned parts
147	        if (!checksums.files.contains("count.txt"))
148	            throw Exception("No checksum for count.txt", ErrorCodes::NO_FILE_IN_DATA_PART);
149	
150	        if (require_part_metadata)
151	        {
152	            if (!checksums.files.contains(mrk_file_name))
153	                throw Exception(
154	                    ErrorCodes::NO_FILE_IN_DATA_PART,
155	                    "No marks file checksum for column in part {}",
156	                    data_part_storage->getFullPath());
157	            if (!checksums.files.contains(DATA_FILE_NAME_WITH_EXTENSION))
158	                throw Exception(
159	                    ErrorCodes::NO_FILE_IN_DATA_PART,
160	                    "No data file checksum for in part {}",
161	                    data_part_storage->getFullPath());
162	        }
163	    }
164	    else
165	    {
166	        {
167	            /// count.txt should be present even in non custom-partitioned parts
168	            std::string file_path = "count.txt";
169	            if (!data_part_storage->exists(file_path) || data_part_storage->getFileSize(file_path) == 0)
170	                throw Exception(
171	                    ErrorCodes::BAD_SIZE_OF_FILE_IN_DATA_PART,
172	                    "Part {} is broken: {} is empty",
173	                    data_part_storage->getRelativePath(),
174	                    std::string(fs::path(data_part_storage->getFullPath()) / file_path));
175	        }
176	
177	        /// Check that marks are nonempty and have the consistent size with columns number.
178	
179	        if (data_part_storage->exists(mrk_file_name))
180	        {
181	            UInt64 file_size = data_part_storage->getFileSize(mrk_file_name);
182	             if (!file_size)
183	                throw Exception(
184	                    ErrorCodes::BAD_SIZE_OF_FILE_IN_DATA_PART,
185	                    "Part {} is broken: {} is empty.",
186	                    data_part_storage->getRelativePath(),
187	                    std::string(fs::path(data_part_storage->getFullPath()) / mrk_file_name));
188	
189	            UInt64 expected_file_size = index_granularity_info.getMarkSizeInBytes(columns.size()) * index_granularity.getMarksCount();
190	            if (expected_file_size != file_size)
191	                throw Exception(
192	                    ErrorCodes::BAD_SIZE_OF_FILE_IN_DATA_PART,
193	                    "Part {} is broken: bad size of marks file '{}': {}, must be: {}",
194	                    data_part_storage->getRelativePath(),
195	                    std::string(fs::path(data_part_storage->getFullPath()) / mrk_file_name),
196	                    std::to_string(file_size), std::to_string(expected_file_size));
197	        }
198	    }
199	}
