17	MergeTreeReaderCompact::MergeTreeReaderCompact(
18	    DataPartCompactPtr data_part_,
19	    NamesAndTypesList columns_,
20	    const StorageMetadataPtr & metadata_snapshot_,
21	    UncompressedCache * uncompressed_cache_,
22	    MarkCache * mark_cache_,
23	    MarkRanges mark_ranges_,
24	    MergeTreeReaderSettings settings_,
25	    ValueSizeMap avg_value_size_hints_,
26	    const ReadBufferFromFileBase::ProfileCallback & profile_callback_,
27	    clockid_t clock_type_)
28	    : IMergeTreeReader(
29	        data_part_,
30	        columns_,
31	        metadata_snapshot_,
32	        uncompressed_cache_,
33	        mark_cache_,
34	        mark_ranges_,
35	        settings_,
36	        avg_value_size_hints_)
37	    , marks_loader(
38	          data_part->data_part_storage,
39	          mark_cache,
40	          data_part->index_granularity_info.getMarksFilePath(MergeTreeDataPartCompact::DATA_FILE_NAME),
41	          data_part->getMarksCount(),
42	          data_part->index_granularity_info,
43	          settings.save_marks_in_cache,
44	          data_part->getColumns().size())
45	{
46	    try
47	    {
48	        size_t columns_num = columns.size();
49	
50	        column_positions.resize(columns_num);
51	        read_only_offsets.resize(columns_num);
52	        auto name_and_type = columns.begin();
53	        for (size_t i = 0; i < columns_num; ++i, ++name_and_type)
54	        {
55	            if (name_and_type->isSubcolumn())
56	            {
57	                auto storage_column_from_part = getColumnFromPart(
58	                    {name_and_type->getNameInStorage(), name_and_type->getTypeInStorage()});
59	
60	                if (!storage_column_from_part.type->tryGetSubcolumnType(name_and_type->getSubcolumnName()))
61	                    continue;
62	            }
63	
64	            auto column_from_part = getColumnFromPart(*name_and_type);
65	
66	            auto position = data_part->getColumnPosition(column_from_part.getNameInStorage());
67	            if (!position && typeid_cast<const DataTypeArray *>(column_from_part.type.get()))
68	            {
69	                /// If array of Nested column is missing in part,
70	                /// we have to read its offsets if they exist.
71	                position = findColumnForOffsets(column_from_part.name);
72	                read_only_offsets[i] = (position != std::nullopt);
73	            }
74	
75	            column_positions[i] = std::move(position);
76	        }
77	
78	        /// Do not use max_read_buffer_size, but try to lower buffer size with maximal size of granule to avoid reading much data.
79	        auto buffer_size = getReadBufferSize(data_part, marks_loader, column_positions, all_mark_ranges);
80	        if (buffer_size)
81	            settings.read_settings = settings.read_settings.adjustBufferSize(buffer_size);
82	
83	        if (!settings.read_settings.local_fs_buffer_size || !settings.read_settings.remote_fs_buffer_size)
84	            throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA, "Cannot read to empty buffer.");
85	
86	        const String path = MergeTreeDataPartCompact::DATA_FILE_NAME_WITH_EXTENSION;
87	        if (uncompressed_cache)
88	        {
89	            auto buffer = std::make_unique<CachedCompressedReadBuffer>(
90	                std::string(fs::path(data_part->data_part_storage->getFullPath()) / path),
91	                [this, path]()
92	                {
93	                    return data_part->data_part_storage->readFile(
94	                        path,
95	                        settings.read_settings,
96	                        std::nullopt, std::nullopt);
97	                },
98	                uncompressed_cache,
99	                /* allow_different_codecs = */ true);
100	
101	            if (profile_callback_)
102	                buffer->setProfileCallback(profile_callback_, clock_type_);
103	
104	            if (!settings.checksum_on_read)
105	                buffer->disableChecksumming();
106	
107	            cached_buffer = std::move(buffer);
108	            data_buffer = cached_buffer.get();
109	            compressed_data_buffer = cached_buffer.get();
110	        }
111	        else
112	        {
113	            auto buffer =
114	                std::make_unique<CompressedReadBufferFromFile>(
115	                    data_part->data_part_storage->readFile(
116	                        path,
117	                        settings.read_settings,
118	                        std::nullopt, std::nullopt),
119	                    /* allow_different_codecs = */ true);
120	
121	            if (profile_callback_)
122	                buffer->setProfileCallback(profile_callback_, clock_type_);
123	
124	            if (!settings.checksum_on_read)
125	                buffer->disableChecksumming();
126	
127	            non_cached_buffer = std::move(buffer);
128	            data_buffer = non_cached_buffer.get();
129	            compressed_data_buffer = non_cached_buffer.get();
130	        }
131	    }
132	    catch (...)
133	    {
134	        storage.reportBrokenPart(data_part);
135	        throw;
136	    }
137	}
