139	size_t MergeTreeReaderCompact::readRows(
140	    size_t from_mark, size_t current_task_last_mark, bool continue_reading, size_t max_rows_to_read, Columns & res_columns)
141	{
142	    if (continue_reading)
143	        from_mark = next_mark;
144	
145	    size_t read_rows = 0;
146	    size_t num_columns = columns.size();
147	    checkNumberOfColumns(num_columns);
148	
149	    MutableColumns mutable_columns(num_columns);
150	    auto column_it = columns.begin();
151	    for (size_t i = 0; i < num_columns; ++i, ++column_it)
152	    {
153	        if (!column_positions[i])
154	            continue;
155	
156	        auto column_from_part = getColumnFromPart(*column_it);
157	        if (res_columns[i] == nullptr)
158	        {
159	            auto serialization = data_part->getSerialization(column_from_part);
160	            res_columns[i] = column_from_part.type->createColumn(*serialization);
161	        }
162	    }
163	
164	    while (read_rows < max_rows_to_read)
165	    {
166	        size_t rows_to_read = data_part->index_granularity.getMarkRows(from_mark);
167	
168	        auto name_and_type = columns.begin();
169	        for (size_t pos = 0; pos < num_columns; ++pos, ++name_and_type)
170	        {
171	            auto column_from_part = getColumnFromPart(*name_and_type);
172	            if (!res_columns[pos])
173	                continue;
174	
175	            try
176	            {
177	                auto & column = res_columns[pos];
178	                size_t column_size_before_reading = column->size();
179	
180	                readData(column_from_part, column, from_mark, current_task_last_mark, *column_positions[pos], rows_to_read, read_only_offsets[pos]);
181	
182	                size_t read_rows_in_column = column->size() - column_size_before_reading;
183	                if (read_rows_in_column != rows_to_read)
184	                    throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA,
185	                        "Cannot read all data in MergeTreeReaderCompact. Rows read: {}. Rows expected: {}.",
186	                        read_rows_in_column, rows_to_read);
187	            }
188	            catch (Exception & e)
189	            {
190	                if (e.code() != ErrorCodes::MEMORY_LIMIT_EXCEEDED)
191	                    storage.reportBrokenPart(data_part);
192	
193	                /// Better diagnostics.
194	                e.addMessage("(while reading column " + column_from_part.name + ")");
195	                throw;
196	            }
197	            catch (...)
198	            {
199	                storage.reportBrokenPart(data_part);
200	                throw;
201	            }
202	        }
203	
204	        ++from_mark;
205	        read_rows += rows_to_read;
206	    }
207	
208	    next_mark = from_mark;
209	
210	    return read_rows;
211	}
