213	void MergeTreeReaderCompact::readData(
214	    const NameAndTypePair & name_and_type, ColumnPtr & column,
215	    size_t from_mark, size_t current_task_last_mark, size_t column_position, size_t rows_to_read, bool only_offsets)
216	{
217	    const auto & [name, type] = name_and_type;
218	
219	    adjustUpperBound(current_task_last_mark); /// Must go before seek.
220	
221	    if (!isContinuousReading(from_mark, column_position))
222	        seekToMark(from_mark, column_position);
223	
224	    auto buffer_getter = [&](const ISerialization::SubstreamPath & substream_path) -> ReadBuffer *
225	    {
226	        if (only_offsets && (substream_path.size() != 1 || substream_path[0].type != ISerialization::Substream::ArraySizes))
227	            return nullptr;
228	
229	        return data_buffer;
230	    };
231	
232	    ISerialization::DeserializeBinaryBulkStatePtr state;
233	    ISerialization::DeserializeBinaryBulkSettings deserialize_settings;
234	    deserialize_settings.getter = buffer_getter;
235	    deserialize_settings.avg_value_size_hint = avg_value_size_hints[name];
236	
237	    if (name_and_type.isSubcolumn())
238	    {
239	        const auto & type_in_storage = name_and_type.getTypeInStorage();
240	        const auto & name_in_storage = name_and_type.getNameInStorage();
241	
242	        auto serialization = data_part->getSerialization(NameAndTypePair{name_in_storage, type_in_storage});
243	        ColumnPtr temp_column = type_in_storage->createColumn(*serialization);
244	
245	        serialization->deserializeBinaryBulkStatePrefix(deserialize_settings, state);
246	        serialization->deserializeBinaryBulkWithMultipleStreams(temp_column, rows_to_read, deserialize_settings, state, nullptr);
247	
248	        auto subcolumn = type_in_storage->getSubcolumn(name_and_type.getSubcolumnName(), temp_column);
249	
250	        /// TODO: Avoid extra copying.
251	        if (column->empty())
252	            column = subcolumn;
253	        else
254	            column->assumeMutable()->insertRangeFrom(*subcolumn, 0, subcolumn->size());
255	    }
256	    else
257	    {
258	        auto serialization = data_part->getSerialization(name_and_type);
259	        serialization->deserializeBinaryBulkStatePrefix(deserialize_settings, state);
260	        serialization->deserializeBinaryBulkWithMultipleStreams(column, rows_to_read, deserialize_settings, state, nullptr);
261	    }
262	
263	    /// The buffer is left in inconsistent state after reading single offsets
264	    if (only_offsets)
265	        last_read_granule.reset();
266	    else
267	        last_read_granule.emplace(from_mark, column_position);
268	}
