288	void MergeTreeReaderCompact::adjustUpperBound(size_t last_mark)
289	{
290	    size_t right_offset = 0;
291	    if (last_mark < data_part->getMarksCount()) /// Otherwise read until the end of file
292	        right_offset = marks_loader.getMark(last_mark).offset_in_compressed_file;
293	
294	    if (right_offset == 0)
295	    {
296	        /// If already reading till the end of file.
297	        if (last_right_offset && *last_right_offset == 0)
298	            return;
299	
300	        last_right_offset = 0; // Zero value means the end of file.
301	        data_buffer->setReadUntilEnd();
302	    }
303	    else
304	    {
305	        if (last_right_offset && right_offset <= last_right_offset.value())
306	            return;
307	
308	        last_right_offset = right_offset;
309	        data_buffer->setReadUntilPosition(right_offset);
310	    }
311	}
