313	bool MergeTreeReaderCompact::isContinuousReading(size_t mark, size_t column_position)
314	{
315	    if (!last_read_granule)
316	        return false;
317	    const auto & [last_mark, last_column] = *last_read_granule;
318	    return (mark == last_mark && column_position == last_column + 1)
319	        || (mark == last_mark + 1 && column_position == 0 && last_column == data_part->getColumns().size() - 1);
320	}
