325	/// A simple class that helps to iterate over 2-dim marks of compact parts.
326	class MarksCounter
327	{
328	public:
329	    MarksCounter(size_t rows_num_, size_t columns_num_)
330	        : rows_num(rows_num_), columns_num(columns_num_) {}
331	
332	    struct Iterator
333	    {
334	        size_t row;
335	        size_t column;
336	        MarksCounter * counter;
337	
338	        Iterator(size_t row_, size_t column_, MarksCounter * counter_)
339	            : row(row_), column(column_), counter(counter_) {}
340	
341	        Iterator operator++()
342	        {
343	            if (column + 1 == counter->columns_num)
344	            {
345	                ++row;
346	                column = 0;
347	            }
348	            else
349	            {
350	                ++column;
351	            }
352	
353	            return *this;
354	        }
355	
356	        bool operator==(const Iterator & other) const { return row == other.row && column == other.column; }
357	        bool operator!=(const Iterator & other) const { return !(*this == other); }
358	    };
359	
360	    Iterator get(size_t row, size_t column) { return Iterator(row, column, this); }
361	    Iterator end() { return get(rows_num, 0); }
362	
363	private:
364	    size_t rows_num;
365	    size_t columns_num;
366	};
