371	    const DataPartPtr & part,
372	    MergeTreeMarksLoader & marks_loader,
373	    const ColumnPositions & column_positions,
374	    const MarkRanges & mark_ranges)
375	{
376	    size_t buffer_size = 0;
377	    size_t columns_num = column_positions.size();
378	    size_t file_size = part->getFileSizeOrZero(MergeTreeDataPartCompact::DATA_FILE_NAME_WITH_EXTENSION);
379	
380	    MarksCounter counter(part->getMarksCount(), part->getColumns().size());
381	
382	    for (const auto & mark_range : mark_ranges)
383	    {
384	        for (size_t mark = mark_range.begin; mark < mark_range.end; ++mark)
385	        {
386	            for (size_t i = 0; i < columns_num; ++i)
387	            {
388	                if (!column_positions[i])
389	                    continue;
390	
391	                auto it = counter.get(mark, *column_positions[i]);
392	                size_t cur_offset = marks_loader.getMark(it.row, it.column).offset_in_compressed_file;
393	
394	                while (it != counter.end() && cur_offset == marks_loader.getMark(it.row, it.column).offset_in_compressed_file)
395	                    ++it;
396	
397	                size_t next_offset = (it == counter.end() ? file_size : marks_loader.getMark(it.row, it.column).offset_in_compressed_file);
398	                buffer_size = std::max(buffer_size, next_offset - cur_offset);
399	            }
400	        }
401	    }
402	
403	    return buffer_size;
404	}
