41	void MergeTreeDataPartWriterCompact::addStreams(const NameAndTypePair & column, const ASTPtr & effective_codec_desc)
42	{
43	    ISerialization::StreamCallback callback = [&](const auto & substream_path)
44	    {
45	        assert(!substream_path.empty());
46	        String stream_name = ISerialization::getFileNameForStream(column, substream_path);
47	
48	        /// Shared offsets for Nested type.
49	        if (compressed_streams.contains(stream_name))
50	            return;
51	
52	        const auto & subtype = substream_path.back().data.type;
53	        CompressionCodecPtr compression_codec;
54	
55	        /// If we can use special codec than just get it
56	        if (ISerialization::isSpecialCompressionAllowed(substream_path))
57	            compression_codec = CompressionCodecFactory::instance().get(effective_codec_desc, subtype.get(), default_codec);
58	        else /// otherwise return only generic codecs and don't use info about data_type
59	            compression_codec = CompressionCodecFactory::instance().get(effective_codec_desc, nullptr, default_codec, true);
60	
61	        UInt64 codec_id = compression_codec->getHash();
62	        auto & stream = streams_by_codec[codec_id];
63	        if (!stream)
64	            stream = std::make_shared<CompressedStream>(plain_hashing, compression_codec);
65	
66	        compressed_streams.emplace(stream_name, stream);
67	    };
68	
69	    ISerialization::SubstreamPath path;
70	    data_part->getSerialization(column)->enumerateStreams(path, callback, column.type);
71	}
