76	/// Get granules for block using index_granularity
77	Granules getGranulesToWrite(const MergeTreeIndexGranularity & index_granularity, size_t block_rows, size_t current_mark, bool last_block)
78	{
79	    if (current_mark >= index_granularity.getMarksCount())
80	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Request to get granules from mark {} but index granularity size is {}", current_mark, index_granularity.getMarksCount());
81	
82	    Granules result;
83	    size_t current_row = 0;
84	    while (current_row < block_rows)
85	    {
86	        size_t expected_rows_in_mark = index_granularity.getMarkRows(current_mark);
87	        size_t rows_left_in_block = block_rows - current_row;
88	        if (rows_left_in_block < expected_rows_in_mark && !last_block)
89	        {
90	            /// Invariant: we always have equal amount of rows for block in compact parts because we accumulate them in buffer.
91	            /// The only exclusion is the last block, when we cannot accumulate more rows.
92	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Required to write {} rows, but only {} rows was written for the non last granule", expected_rows_in_mark, rows_left_in_block);
93	        }
94	
95	        result.emplace_back(Granule{
96	            .start_row = current_row,
97	            .rows_to_write = std::min(rows_left_in_block, expected_rows_in_mark),
98	            .mark_number = current_mark,
99	            .mark_on_start = true,
100	            .is_complete = (rows_left_in_block >= expected_rows_in_mark)
101	        });
102	        current_row += result.back().rows_to_write;
103	        current_mark++;
104	    }
105	
106	    return result;
107	}
