118	    ISerialization::SerializeBinaryBulkSettings serialize_settings;
119	
120	    serialize_settings.getter = stream_getter;
121	    serialize_settings.position_independent_encoding = true; //-V1048
122	    serialize_settings.low_cardinality_max_dictionary_size = 0; //-V1048
