131	void MergeTreeDataPartWriterCompact::write(const Block & block, const IColumn::Permutation * permutation)
132	{
133	    /// Fill index granularity for this block
134	    /// if it's unknown (in case of insert data or horizontal merge,
135	    /// but not in case of vertical merge)
136	    if (compute_granularity)
137	    {
138	        size_t index_granularity_for_block = computeIndexGranularity(block);
139	        fillIndexGranularity(index_granularity_for_block, block.rows());
140	    }
141	
142	    Block result_block = permuteBlockIfNeeded(block, permutation);
143	
144	    if (!header)
145	        header = result_block.cloneEmpty();
146	
147	    columns_buffer.add(result_block.mutateColumns());
148	    size_t current_mark_rows = index_granularity.getMarkRows(getCurrentMark());
149	    size_t rows_in_buffer = columns_buffer.size();
150	
151	    if (rows_in_buffer >= current_mark_rows)
152	    {
153	        Block flushed_block = header.cloneWithColumns(columns_buffer.releaseColumns());
154	        auto granules_to_write = getGranulesToWrite(index_granularity, flushed_block.rows(), getCurrentMark(), /* last_block = */ false);
155	        writeDataBlockPrimaryIndexAndSkipIndices(flushed_block, granules_to_write);
156	        setCurrentMark(getCurrentMark() + granules_to_write.size());
157	    }
158	}
