160	void MergeTreeDataPartWriterCompact::writeDataBlockPrimaryIndexAndSkipIndices(const Block & block, const Granules & granules_to_write)
161	{
162	    writeDataBlock(block, granules_to_write);
163	
164	    if (settings.rewrite_primary_key)
165	    {
166	        Block primary_key_block = getBlockAndPermute(block, metadata_snapshot->getPrimaryKeyColumns(), nullptr);
167	        calculateAndSerializePrimaryIndex(primary_key_block, granules_to_write);
168	    }
169	
170	    Block skip_indices_block = getBlockAndPermute(block, getSkipIndicesColumns(), nullptr);
171	    calculateAndSerializeSkipIndices(skip_indices_block, granules_to_write);
172	}
