174	void MergeTreeDataPartWriterCompact::writeDataBlock(const Block & block, const Granules & granules)
175	{
176	    for (const auto & granule : granules)
177	    {
178	        data_written = true;
179	
180	        auto name_and_type = columns_list.begin();
181	        for (size_t i = 0; i < columns_list.size(); ++i, ++name_and_type)
182	        {
183	            /// Tricky part, because we share compressed streams between different columns substreams.
184	            /// Compressed streams write data to the single file, but with different compression codecs.
185	            /// So we flush each stream (using next()) before using new one, because otherwise we will override
186	            /// data in result file.
187	            CompressedStreamPtr prev_stream;
188	            auto stream_getter = [&, this](const ISerialization::SubstreamPath & substream_path) -> WriteBuffer *
189	            {
190	                String stream_name = ISerialization::getFileNameForStream(*name_and_type, substream_path);
191	
192	                auto & result_stream = compressed_streams[stream_name];
193	                /// Write one compressed block per column in granule for more optimal reading.
194	                if (prev_stream && prev_stream != result_stream)
195	                {
196	                    /// Offset should be 0, because compressed block is written for every granule.
197	                    assert(result_stream->hashing_buf.offset() == 0);
198	                    prev_stream->hashing_buf.next();
199	                }
200	
201	                prev_stream = result_stream;
202	
203	                return &result_stream->hashing_buf;
204	            };
205	
206	
207	            writeIntBinary(plain_hashing.count(), marks);
208	            writeIntBinary(static_cast<UInt64>(0), marks);
209	
210	            writeColumnSingleGranule(
211	                block.getByName(name_and_type->name), data_part->getSerialization(*name_and_type),
212	                stream_getter, granule.start_row, granule.rows_to_write);
213	
214	            /// Each type always have at least one substream
215	            prev_stream->hashing_buf.next(); //-V522
216	        }
217	
218	        writeIntBinary(granule.rows_to_write, marks);
219	    }
220	}
