222	void MergeTreeDataPartWriterCompact::fillDataChecksums(IMergeTreeDataPart::Checksums & checksums)
223	{
224	    if (columns_buffer.size() != 0)
225	    {
226	        auto block = header.cloneWithColumns(columns_buffer.releaseColumns());
227	        auto granules_to_write = getGranulesToWrite(index_granularity, block.rows(), getCurrentMark(), /* last_block = */ true);
228	        if (!granules_to_write.back().is_complete)
229	        {
230	            /// Correct last mark as it should contain exact amount of rows.
231	            index_granularity.popMark();
232	            index_granularity.appendMark(granules_to_write.back().rows_to_write);
233	        }
234	        writeDataBlockPrimaryIndexAndSkipIndices(block, granules_to_write);
235	    }
236	
237	#ifndef NDEBUG
238	    /// Offsets should be 0, because compressed block is written for every granule.
239	    for (const auto & [_, stream] : streams_by_codec)
240	        assert(stream->hashing_buf.offset() == 0);
241	#endif
242	
243	    if (with_final_mark && data_written)
244	    {
245	        for (size_t i = 0; i < columns_list.size(); ++i)
246	        {
247	            writeIntBinary(plain_hashing.count(), marks);
248	            writeIntBinary(static_cast<UInt64>(0), marks);
249	        }
250	        writeIntBinary(static_cast<UInt64>(0), marks);
251	    }
252	
253	    plain_file->next();
254	    marks.next();
255	    addToChecksums(checksums);
256	
257	    plain_file->preFinalize();
258	    marks_file->preFinalize();
259	}
