272	static void fillIndexGranularityImpl(
273	    MergeTreeIndexGranularity & index_granularity,
274	    size_t index_offset,
275	    size_t index_granularity_for_block,
276	    size_t rows_in_block)
277	{
278	    for (size_t current_row = index_offset; current_row < rows_in_block; current_row += index_granularity_for_block)
279	    {
280	        size_t rows_left_in_block = rows_in_block - current_row;
281	
282	        /// Try to extend last granule if block is large enough
283	        ///  or it isn't first in granule (index_offset != 0).
284	        if (rows_left_in_block < index_granularity_for_block &&
285	            (rows_in_block >= index_granularity_for_block || index_offset != 0))
286	        {
287	            // If enough rows are left, create a new granule. Otherwise, extend previous granule.
288	            // So, real size of granule differs from index_granularity_for_block not more than 50%.
289	            if (rows_left_in_block * 2 >= index_granularity_for_block)
290	                index_granularity.appendMark(rows_left_in_block);
291	            else
292	                index_granularity.addRowsToLastMark(rows_left_in_block);
293	        }
294	        else
295	        {
296	            index_granularity.appendMark(index_granularity_for_block);
297	        }
298	    }
299	}
