301	void MergeTreeDataPartWriterCompact::fillIndexGranularity(size_t index_granularity_for_block, size_t rows_in_block)
302	{
303	    size_t index_offset = 0;
304	    if (index_granularity.getMarksCount() > getCurrentMark())
305	        index_offset = index_granularity.getMarkRows(getCurrentMark()) - columns_buffer.size();
306	
307	    fillIndexGranularityImpl(
308	        index_granularity,
309	        index_offset,
310	        index_granularity_for_block,
311	        rows_in_block);
312	}
