314	void MergeTreeDataPartWriterCompact::addToChecksums(MergeTreeDataPartChecksums & checksums)
315	{
316	    String data_file_name = MergeTreeDataPartCompact::DATA_FILE_NAME_WITH_EXTENSION;
317	    String marks_file_name = MergeTreeDataPartCompact::DATA_FILE_NAME +  marks_file_extension;
318	
319	    size_t uncompressed_size = 0;
320	    CityHash_v1_0_2::uint128 uncompressed_hash{0, 0};
321	
322	    for (const auto & [_, stream] : streams_by_codec)
323	    {
324	        uncompressed_size += stream->hashing_buf.count();
325	        auto stream_hash = stream->hashing_buf.getHash();
326	        uncompressed_hash = CityHash_v1_0_2::CityHash128WithSeed(
327	            reinterpret_cast<char *>(&stream_hash), sizeof(stream_hash), uncompressed_hash);
328	    }
329	
330	    checksums.files[data_file_name].is_compressed = true;
331	    checksums.files[data_file_name].uncompressed_size = uncompressed_size;
332	    checksums.files[data_file_name].uncompressed_hash = uncompressed_hash;
333	    checksums.files[data_file_name].file_size = plain_hashing.count();
334	    checksums.files[data_file_name].file_hash = plain_hashing.getHash();
335	
336	    checksums.files[marks_file_name].file_size = marks.count();
337	    checksums.files[marks_file_name].file_hash = marks.getHash();
338	}
